//! `expand_suite` codegen reproduction tests, dogfooded on rudzio.

use syn::{ItemMod, parse_quote};

use rudzio::common::context::{Suite, Test};
use rudzio::runtime::futures::ThreadPool;
use rudzio_macro_internals::parse::MainArgs;
use rudzio_macro_internals::suite_codegen::expand_suite;

#[rudzio::suite([
    (runtime = ThreadPool::new, suite = Suite, test = Test),
])]
mod tests {
    use super::{ItemMod, MainArgs, Test, expand_suite, parse_quote};

    /// Bug #5: `#[rudzio::suite]` must register tests generated by
    /// `macro_rules!`. Such an invocation reaches the attribute macro as
    /// a `syn::Item::Macro` (pre-expansion), so `expand_suite` — which
    /// only scans `syn::Item::Fn` — currently sees no test functions and
    /// bails with `Err("no test functions found in module ...")`.
    #[rudzio::test]
    fn macro_rules_generated_test_is_registered(_ctx: &Test) -> anyhow::Result<()> {
        let args: MainArgs = parse_quote!([
            (runtime = rudzio::runtime::futures::ThreadPool::new,
             suite = rudzio::common::context::Suite,
             test = rudzio::common::context::Test),
        ]);

        // `make_test!(a);` parses as `syn::Item::Macro` — the exact shape
        // a `macro_rules!` invocation takes in item position. There is no
        // `Item::Fn` in this body, mirroring the pre-expansion AST the
        // `#[rudzio::suite]` attribute actually receives.
        let input_mod: ItemMod = parse_quote! {
            mod tests {
                make_test!(a);
            }
        };

        // Correct behavior: the expansion succeeds and registers the
        // macro-generated test. Under the current code this returns
        // Err("no test functions found in module - add functions with
        // #[rudzio::test] attribute"), so this assertion fails until
        // Bug #5 is fixed.
        anyhow::ensure!(
            expand_suite(&args, input_mod).is_ok(),
            "expand_suite must register a macro_rules!-generated test instead of rejecting the module",
        );
        Ok(())
    }
}
